<script lang="ts">import {notificationPreferences,saveNotificationPreferences} from "./notification-settings";import {translator} from "./i18n";export let language:"ru"|"ro";$:t=translator(language);function save(){saveNotificationPreferences($notificationPreferences);}</script>
<section class="panel notification-settings"><h2>{t("Уведомления и звуки","Notificări și sunete")}</h2><label class="check-row"><input type="checkbox" bind:checked={$notificationPreferences.enabled} onchange={save}/>{t("Показывать уведомления","Afișare notificări")}</label><label class="check-row"><input type="checkbox" bind:checked={$notificationPreferences.sound} onchange={save}/>{t("Системный звук","Sunet de sistem")}</label><label class="check-row"><input type="checkbox" bind:checked={$notificationPreferences.animation} onchange={save}/>{t("Анимация появления","Animație de apariție")}</label><label>{t("Время показа","Durata afișării")}<select bind:value={$notificationPreferences.seconds} onchange={save}>{#each [3,6,10,15] as seconds}<option value={seconds}>{seconds} {t("сек.","sec.")}</option>{/each}</select></label><p>{t("Ошибки остаются на экране до закрытия. При наведении таймер приостанавливается.","Erorile rămân afișate până la închidere. Cronometrul se oprește când cursorul este deasupra notificării.")}</p></section>
